{"command":"cat > gen_hanoi.py << 'EOF'
import json, sys
sys.setrecursionlimit(10000)
def hanoi(n, src, dst, aux):
    if n == 0:
        return []
    return hanoi(n-1, src, aux, dst) + [[n, src, dst]] + hanoi(n-1, aux, dst, src)
moves = hanoi(8, 0, 2, 1)
if len(sys.argv) == 3:
    start = int(sys.argv[1])
    end = int(sys.argv[2])
    print(json.dumps(moves[start:end]))
else:
    print(json.dumps(moves))
EOF"}
